// Qdrant search response
const inputData = $input.first().json;
let formatted_examples = "";

// 'result' holds the retrieved examples (count = limit in the search node)
const searchResults = inputData.result || [];

searchResults.forEach((item, index) => {
    const p = item.payload || {};

    // Labels may be an array or a comma-separated string
    let labels = "None (Not a Privacy Issue)";

    if (p.true_labels) {
        if (Array.isArray(p.true_labels) && p.true_labels.length > 0) {
            labels = p.true_labels.join(", ");
        } else if (typeof p.true_labels === 'string' && p.true_labels.trim() !== '') {
            labels = p.true_labels;
        }
    }

    // Body on one line, first 200 characters
    let cleanBody = (p.body || "").replace(/\n/g, " ");
    if (cleanBody.length > 200) {
        cleanBody = cleanBody.substring(0, 200) + "...";
    }

    // Fallback for an empty title
    const title = p.title || "No Title Provided";

    formatted_examples += `Example ${index + 1}:\n`;
    formatted_examples += `Title: ${title}\n`;
    formatted_examples += `Body: ${cleanBody}\n`;
    formatted_examples += `Correct Labels: ${labels}\n`;
    formatted_examples += `-------------------\n`;
});

// Return a single item: all_formatted_examples
return [{
    json: {
        all_formatted_examples: formatted_examples
    }
}];

