// 1. Fetch Taxonomy globally
let taxonomyItems;
try { 
  // Ensure the name matches your actual node name
  taxonomyItems = $items("Taxonomy JSON"); 
} catch (e) { 
  return [{ json: { "Error": "Taxonomy node not found. Ensure your taxonomy node is named exactly 'Taxonomy JSON1'." } }]; 
}

const flatTaxonomy = {};
function crawl(obj) {
  if (!obj || typeof obj !== 'object') return;
  for (const key in obj) {
    const value = obj[key];
    if (value && typeof value === 'object') {
      if (value.label) flatTaxonomy[key.trim()] = { label: value.label, sources: value.sources || [] };
      crawl(value);
    }
  }
}
taxonomyItems.forEach(item => crawl(item.json.root || item.json));

// 2. Process Input and Extract JSON securely
return $input.all().map(item => {
  let rawText = item.json.output || "";
  let extracted = {};

  // If the incoming item already has an error (from a previous node), pass it through
  if (item.json.error || item.json.Error) {
    return { json: item.json };
  }

  try {
    // We completely drop the Regex to avoid "nested markdown" traps.
    // Instead, we find the absolute first '{' and the absolute last '}'
    const startIndex = rawText.indexOf('{');
    const endIndex = rawText.lastIndexOf('}');

    if (startIndex !== -1 && endIndex !== -1 && endIndex > startIndex) {
      // Slices out ONLY the complete JSON object, ignoring any backticks or chat outside of it
      let cleanJsonString = rawText.substring(startIndex, endIndex + 1);

      // --- NEW SANITIZATION STEP ---
      // AI sometimes leaves raw newlines or tabs inside strings, which breaks JSON.parse().
      // This state machine safely escapes control characters ONLY if they are inside double quotes.
      let isInsideString = false;
      let cleanJsonStringEscaped = "";

      for (let i = 0; i < cleanJsonString.length; i++) {
        const char = cleanJsonString[i];

        // Toggle "Inside String" state when we hit an unescaped quote
        if (char === '"') {
          let backslashCount = 0;
          let j = i - 1;
          while (j >= 0 && cleanJsonString[j] === '\\') {
            backslashCount++;
            j--;
          }
          if (backslashCount % 2 === 0) {
            isInsideString = !isInsideString;
          }
        }

        // If we are inside a text string, sanitize bad control characters
        if (isInsideString) {
          if (char === '\n') cleanJsonStringEscaped += '\\n';
          else if (char === '\r') cleanJsonStringEscaped += '\\r';
          else if (char === '\t') cleanJsonStringEscaped += '\\t';
          else if (char.charCodeAt(0) < 32) { /* Ignore other invalid control characters */ }
          else cleanJsonStringEscaped += char;
        } else {
          // Outside quotes, leave structural newlines alone
          cleanJsonStringEscaped += char;
        }
      }

      cleanJsonString = cleanJsonStringEscaped;
      // --- END SANITIZATION STEP ---

      extracted = JSON.parse(cleanJsonString);
    } else {
      return { json: { "Error": "No JSON brackets found in the AI output.", "Raw": rawText } };
    }
  } catch (e) {
    return { json: { "Error": "Failed to parse extracted JSON", "Details": e.message, "Raw": rawText } };
  }

  // 3. Match against Taxonomy
  // Changed from Taxonomy_IDs to Ranked_Taxonomy_IDs to match the updated prompt schema
  let rawIds = extracted["Ranked_Taxonomy_IDs"] || [];
  let ids = Array.isArray(rawIds) ? rawIds : String(rawIds).split(',').map(id => id.trim());

  // Filter out any empty string entries
  ids = ids.filter(id => id !== "");

  const foundLabels = [];
  const foundSourcesList = [];

  ids.forEach(id => {
    const match = flatTaxonomy[id];
    if (match) {
      foundLabels.push(match.label);
      foundSourcesList.push(`[${(match.sources || []).sort((a,b)=>a-b).join(',')}]`);
    }
  });

  // 4. Return the final formatted mapping for your GitHub privacy classification
  return {
    json: {
      "Issue_ID": extracted.Issue_ID || item.json.Issue_ID || "",
      "Title": extracted.Issue_Title || "",
      "Issue_Body": extracted.Issue_Body || item.json.Issue_Body || "", 
      "Taxonomy ID": ids.join(", "),
      "Taxonomy issue": foundLabels.join(", \n"),
      "PbD principle": foundSourcesList.join(" ; "),
      "Privacy_issue": extracted.is_privacy_issue || false,
      "Reason": extracted.Reason || ""
    }
  };
});

// 1. Fetch Taxonomy globally by Node Name
const taxonomyItems = $items("Taxonomy JSON");

if (!taxonomyItems || taxonomyItems.length === 0) {
  return [{ json: { "Error": "Can't find Taxonomy JSON. Check spelling!" } }];
}

// Combine all taxonomy data safely
let combinedTaxonomy = {};
taxonomyItems.forEach(item => {
    Object.assign(combinedTaxonomy, item.json.root || item.json);
});

// Build the lookup map
const flatTaxonomy = {};
function crawl(obj) {
  if (!obj || typeof obj !== 'object') return;
  for (const key in obj) {
    const value = obj[key];
    if (value && typeof value === 'object') {
      if (value.label) {
        flatTaxonomy[key.trim()] = {
          label: value.label,
          sources: value.sources || []
        };
      }
      crawl(value); // Keep digging deeper
    }
  }
}
crawl(combinedTaxonomy);

// 2. Process ONLY the unique items coming in from the connected wire
return $input.all().map(item => {
  const data = item.json;

  // Grab the ID and clean it up
  let rawIds = data["Taxonomy ID"] || data["Taxonomy_IDs"] || "";
  let ids = [];

  if (Array.isArray(rawIds)) {
    ids = rawIds.map(id => String(id).trim());
  } else if (typeof rawIds === 'string') {
    ids = rawIds.split(',').map(id => id.trim()).filter(id => id !== "");
  } else if (rawIds !== null && rawIds !== undefined) {
    ids = [String(rawIds).trim()];
  }

  const foundLabels = [];
  const foundSourcesList = []; // This will hold our separate arrays like ["[1,2]", "[3,4]"]

  // Match our Issue IDs against the Taxonomy Map
  ids.forEach(id => {
    const match = flatTaxonomy[id];
    if (match) {
      foundLabels.push(match.label);

      // NEW LOGIC: Format the sources specifically for THIS ID
      if (Array.isArray(match.sources)) {
        // Sort the numbers and turn them into a string like "[1,2,3]"
        let sortedSources = [...match.sources].sort((a,b) => a - b);
        foundSourcesList.push(JSON.stringify(sortedSources));
      } else {
        foundSourcesList.push("[]"); // Fallback if no sources exist for this ID
      }
    }
  });

  // 3. Output the exact final columns (including the new "Reason" column)
  return {
    json: {
      "Issue_ID": data.Issue_ID || "",
      "Title": data.Title || data.Issue_Title || "",
      "Body": data.Body || data.Issue_Body || "",
      "Taxonomy ID": ids.join(", "),
      "Taxonomy issue": foundLabels.join(", \n"),
      "PbD principle": foundSourcesList.join(" ; "), 
      "Privacy_issue": data.Privacy_issue !== undefined ? data.Privacy_issue : (data.is_privacy_issue || false),
      "Reason": data.Reason || ""
    }
  };
});
